2	  "$schema": "http://json-schema.org/draft-07/schema#",
3	  "title": "entity-extract page output (concepts.json)",
4	  "description": "单页实体抽取产出契约。每页目录 output/concepts.json 必须符合本 schema；collect 用同一份校验。",
5	  "type": "object",
6	  "required": [
7	    "concepts"
8	  ],
9	  "additionalProperties": true,
10	  "properties": {
11	    "concepts": {
12	      "type": "array",
13	      "items": {
14	        "$ref": "#/definitions/concept"
15	      }
16	    },
17	    "notes": {
18	      "type": "array",
19	      "items": {
20	        "type": "string"
21	      }
22	    }
23	  },
